@Component("kYCDocument-handler")
@ProcessingGroup("kYCDocument-processing-group")
public class KYCDocumentEventHandler {
	
	// core constructor
	KYCDocumentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateKYCDocumentEvent
     */
    @EventHandler
    public void handle( CreateKYCDocumentEvent event) {
        entityManager.persist(new KYCDocument(event.getKYCDocumentId(), event.getReference(), event.getIssuedCountry(), event.getExpirationDate(), event.getKycProfile(), event.getDocumentType(), event.getStatus()));
    }

    /*
     * @param	event UpdateKYCDocumentEvent
     */
    @EventHandler
    public KYCDocument handle( UpdateKYCDocumentEvent event) {
    	entityManager.merge(new KYCDocument(event.getKYCDocumentId(), event.getReference(), event.getIssuedCountry(), event.getExpirationDate(), event.getKycProfile(), event.getDocumentType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteKYCDocumentEvent
     */
    @EventHandler
    public void on( DeleteKYCDocumentEvent event) {
    	KYCDocument entity = new KYCDocument();
   
    	// ------------------------------------------
    	// apply the KYCDocumentId
    	// ------------------------------------------
    	entity.setKYCDocumentId( event.getKYCDocumentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final KYCDocumentRepository kYCDocumentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(KYCDocumentEventHandler.class.getName());

}
